public static int echo(int n) {
    if (n < 10) {
        return n;
    }
    return echo(n / 10) + n % 10;
}

public static int koepfe(int n) {
    if (n <= 1) {
        return 1;
    }
    return koepfe(n - 1) + koepfe(n - 2);
}

// soll 0 + 1 + 2 + ... + n liefern
public static int summeBis(int n) {
    return n + summeBis(n - 1);
}
// soll basis hoch exponent liefern
public static int potenz(int basis, int exponent) {
    if (exponent == 0) {
        return 1;
    }
    return basis * potenz(basis, exponent);
}
// soll n + (n - 2) + (n - 4) + ... liefern, z. B. 7 + 5 + 3 + 1 = 16
public static int jedeZweite(int n) {
    if (n == 0) {
        return 0;
    }
    return n + jedeZweite(n - 2);
}

