public static int zaehleAb(String s, char c, int i) {
    if (i == s.length()) {
        return 0;
    }
    if (s.charAt(i) == c) {
        return 1 + zaehleAb(s, c, i + 1);
    }
    return zaehleAb(s, c, i + 1);
}

