public static int binaerRek(int[] r, int x, int lo, int hi) {
    if (lo > hi) {
        return -1;
    }
    int mid = (lo + hi) / 2;
    if (r[mid] == x) {
        return mid;
    }
    if (r[mid] < x) {
        return binaerRek(r, x, mid + 1, hi);
    }
    return binaerRek(r, x, lo, mid - 1);
}

public static int maximumTH(int[] r, int von, int bis) {
    if (von == bis) {
        return r[von];
    }
    int mitte = (von + bis) / 2;
    int links = maximumTH(r, von, mitte);
    int rechts = maximumTH(r, mitte + 1, bis);
    if (links > rechts) {
        return links;
    }
    return rechts;
}

public static int zerlege(int[] r, int lo, int hi) {
    int pivot = r[lo];
    int grenze = lo;
    for (int i = lo + 1; i <= hi; i++) {
        if (r[i] < pivot) {
            grenze = grenze + 1;
            int hilf = r[grenze];
            r[grenze] = r[i];
            r[i] = hilf;
        }
    }
    int hilf = r[lo];
    r[lo] = r[grenze];
    r[grenze] = hilf;
    return grenze;
}

public static void raetsel(int[] r, int n) {
    if (n <= 1) {
        return;
    }
    int m = 0;
    for (int i = 1; i < n; i++) {
        if (r[i] > r[m]) {
            m = i;
        }
    }
    int hilf = r[m];
    r[m] = r[n - 1];
    r[n - 1] = hilf;
    raetsel(r, n - 1);
}
